    async def limit(
        self,
        *,
        bucket: str,
        key: str,
        idempotency_key: typing.Optional[str] = None,
        cost: typing.Optional[int] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> RiskLimit:
        """
        Takes `cost` tokens (default 1) from `key`'s share of one of your buckets and says whether to let the request through: a 200 either way, with `allowed`. Denied requests take nothing. Each key has its own bucket of `burst` tokens refilling at `limit` per `period_seconds` (GCRA, the algorithm coss.com limits its own API with). coss.com keeps only a keyed hash of `key`. While coss.com can't count, the bucket's `on_failure` answers and `degraded` is true.

        Parameters
        ----------
        bucket : str
            The bucket's name.

        key : str
            Who or what is limited: a user id, an email address, an IP address… coss.com keeps only a keyed hash of it.

        idempotency_key : typing.Optional[str]
            Makes retries safe: a repeated allowed check with the same key is answered again without taking more tokens, for an hour. 1-256 characters.

        cost : typing.Optional[int]
            Tokens this request takes. Default 1.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        RiskLimit
            The answer for this request.

        Examples
        --------
        import asyncio

        from coss import AsyncCoss

        client = AsyncCoss(
            "2026-10-10",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.risk.limit(
                idempotency_key="welcome-user-123",
                bucket="password_reset",
                key="ada@example.com",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.limit(
            bucket=bucket, key=key, idempotency_key=idempotency_key, cost=cost, request_options=request_options
        )
        return _response.data

